 $('.layer-controls').insertAdjacentHTML('afterend',`<div class="layer-fill-row"><label title="Fill chỉ giảm nội dung, hiệu ứng vẫn giữ riêng">Fill <input id="layer-fill" type="number" min="0" max="100" value="100" aria-label="Layer fill"><span>%</span></label><button id="layer-lock" aria-label="Khóa lớp" aria-pressed="false">${icon('lock')}<span>Khóa lớp</span></button></div>`);
