 $('#workspace-preset').value=prefs.workspace;
 function applyLayout(){dock.style.setProperty('--dock-width',clamp(Number(prefs.dockWidth)||336,300,460)+'px');$('#color-content').hidden=!prefs.colorOpen;$('#color-collapse').setAttribute('aria-expanded',String(prefs.colorOpen));$('#color-collapse').setAttribute('aria-label',prefs.colorOpen?'Thu panel màu':'Mở panel màu');$('#color-section').classList.toggle('expanded',prefs.colorOpen);nav.hidden=!prefs.infoVisible;$('.properties-tabs').hidden=$('#properties').hidden=!prefs.propertiesVisible;$('#app').dataset.workspace=prefs.workspace;}
 function setWorkspace(mode){prefs.workspace=mode;prefs.colorOpen=mode==='design'&&window.innerHeight>=820;prefs.infoVisible=mode==='photo';prefs.propertiesVisible=true;$('#workspace-preset').value=mode;applyLayout();renderColor();save();api.onLayout();}
