 function applyFill(settings){const d=api.doc();if(!d)return;let l=api.layer();if(l?.type==='shape'&&!effectiveLocked(d,l)){Object.assign(l,settings);api.commit(settings.patternFill?'Pattern fill':'Gradient fill');}else{const created=createLayer('shape',{name:settings.patternFill?'Pattern · '+PATTERNS.find(p=>p[0]===settings.patternFill.kind)?.[1]:'Gradient',shape:'rect',width:d.width,height:d.height,...settings});api.addLayer(created,'Add fill layer');}}
